with items := to_json($$[{"slug":"a","title":"T","summary":"S","body":"B","section":"sec","published":true}]$$)
for item in json_array_unpack(items) union (
    insert Article {
        slug := <str>item['slug'],
        title := <str>item['title'],
        summary := <str>item['summary'],
        body := <str>item['body'],
        section := <str>item['section'],
        published := <bool>item['published'],
    }
    unless conflict on .slug
    else (
        update Article set {
            title := <str>item['title'],
            summary := <str>item['summary'],
            body := <str>item['body'],
            section := <str>item['section'],
            published := <bool>item['published'],
        }
    )
);
EOF
